* {
  box-sizing: border-box;
}

.card {
  width: 320px; /* includes padding and border */
  padding: 16px;
  border: 2px solid #333;
  margin: 0 auto 24px; /* centers, 24px below */
}

.card + .card {
  margin-top: 0; /* adjacent margins collapse */
}

.card {
  position: relative; /* positioning context for children */
  padding: 24px;
}

.badge {
  position: absolute;
  top: -8px;
  right: -8px;
  z-index: 10;
}

.sticky-bar {
  position: sticky;
  top: 0; /* sticks once scrolled to top */
}

.nav {
  display: flex;
  justify-content: space-between; /* main axis */
  align-items: center;           /* cross axis */
  gap: 16px;
  flex-wrap: wrap;
}

.nav .spacer {
  flex: 1 1 auto; /* grows to push items apart */
}

.grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));
  gap: 24px;
}

.card--wide {
  grid-column: span 2; /* occupy two tracks */
}

/* 1fr = one share of leftover track space */

html {
  font-size: 100%; /* 16px default; rem respects user settings */
}

h1 {
  font-size: clamp(1.5rem, 4vw, 2.5rem);
}

/* mobile-first: base CSS targets small screens */
@media (min-width: 768px) {
  .nav-links {
    display: flex;
  }
}

/* never remove focus rings without a replacement */
button:focus-visible {
  outline: 2px solid #2563eb;
  outline-offset: 2px;
}

a:focus-visible {
  outline: 2px dashed #b45309;
}

/* tabindex="-1" keeps an element out of the tab
   order but still allows focus() from scripts —
   useful for skip links and dialogs. */

:root {
  /* contrast ratios measured against white */
  --text: #1a1a1a;    /* 17:1 */
  --muted: #595959;   /* 7:1  */
  --accent: #b45309;  /* 5:1  */
}

@media (prefers-reduced-motion: reduce) {
  * {
    animation-duration: 0.01ms !important;
    transition-duration: 0.01ms !important;
  }
}
